#!/usr/bin/env node
// Bakes the pattern presets (scripts/lib/pattern-presets.mjs) into assets/patterns/generated/ as
// standalone SVG files, for CMS, print and Python consumers that cannot run the renderer.
//
//   node scripts/build-patterns.mjs          # write
//   node scripts/build-patterns.mjs --check  # fail if a file is missing, differs or is unexpected
//
// The files are GENERATED by the motif engine (renderMotifPattern), system work and not supplied
// by Sesc. The four official patterns in assets/patterns/ are never touched. README.md in the
// output directory is hand-written and the only other file allowed there.
import { readFileSync, writeFileSync, existsSync, readdirSync, mkdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { loadMotifEngine } from './lib/load-motif-engine.mjs';
import { PRESETS, presetFileName, presetSvgFile } from './lib/pattern-presets.mjs';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const DIR = join(ROOT, 'assets', 'patterns', 'generated');
const REL = 'assets/patterns/generated';
const KEEP = new Set(['README.md']);
const checkOnly = process.argv.includes('--check');

const engine = await loadMotifEngine();
const wanted = new Map(PRESETS.map((p) => [presetFileName(p), presetSvgFile(engine, p)]));

let stale = false;
const problem = (msg) => { stale = true; console.log(msg); };

if (!checkOnly) mkdirSync(DIR, { recursive: true });
for (const [file, content] of wanted) {
  const p = join(DIR, file);
  const exists = existsSync(p);
  if (exists && readFileSync(p, 'utf8') === content) continue;
  if (checkOnly) { problem(`${exists ? 'out of date' : 'missing'}: ${REL}/${file}`); continue; }
  writeFileSync(p, content);
  console.log(`wrote ${REL}/${file}`);
}

const present = existsSync(DIR) ? readdirSync(DIR) : [];
for (const file of present) {
  if (wanted.has(file) || KEEP.has(file)) continue;
  problem(`unexpected file: ${REL}/${file}${checkOnly ? '' : ' (not a preset; remove it)'}`);
}

if (!stale) console.log(`patterns up to date (${wanted.size} presets)`);
process.exit(stale && (checkOnly || present.some((f) => !wanted.has(f) && !KEEP.has(f))) ? 1 : 0);
